 */
public class StringUtils_indexOfAny_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;









    @Test
    public void testIndexOfAny_MultipleMatches_ReturnsFirstOccurrence() {
        // Covers: Multiple matches, ret updated to the minimum index found
        String[] searchStrs = {"c", "a", "b"};
        // 'a' is at 0, 'b' is at 1, 'c' is at 2. Min is 0.
        assertEquals(0, StringUtils.indexOfAny("abc", searchStrs));
    }










